%% SPRING-MASS-DAMPER SYSTEM WITH STATE OBSERVER
% This script demonstrates state reconstruction using an observer.
% Both noise-free and noisy observer results are plotted together.

clc; clear; close all;
%%

%% ---------------------- System properties ----------------------
m = 10;     % mass (kg)
k = 1000;   % spring constant (N/m)
c = 10;     % damping coefficient (Ns/m)
u = 0;      % external force input (N)
%%

%% ---------------------- System definition ----------------------
A = [0 1; -k/m -c/m];   % state matrix
B = [0; 1/m];           % input matrix
C = [1 0];              % output matrix
% system poles
p_s = eig(A) %[output:61a4c852]
% Observer pole locations (must be faster than system poles)
p_o = [-0.1, -0.2];

% Observer gain (dual system approach)
Ke = place(A', C', p_o)';

t_sim = 0:0.01:10; % simulation time vector
%%

%% ---------------------- System dynamics ----------------------
x0 = [-2; 0]; % released from x = -2 m at rest
[t, x] = ode45(@(t, x) smd(x, A, B, u), t_sim, x0);
%%

y = (C * x')'; % measured displacement
%%

%% ---------------------- Add measurement noise ----------------------
y_noise = awgn(y, 4); % add 50 dB noise
%%

%% ---------------------- Observer calculations ----------------------
x0_hat = [-10; 1]; % initial estimate
%%

% Noise-free observer
[t_o, x_hat] = ode45(@(t_o, x_t) obs(t_o, x_t, A, B, C, u, Ke, y, t), t_sim, x0_hat);
%%

% Noisy observer
[t_o_noise, x_hat_noise] = ode45(@(t_o, x_t) obs(t_o, x_t, A, B, C, u, Ke, y_noise, t), t_sim, x0_hat);
%%

%% ---------------------- Combined Plots ----------------------
figure('Name', 'Observer Comparison (Noise vs No Noise)', 'NumberTitle', 'off'); %[output:88036ffd]

% --- Displacement ---
subplot(2,2,1); %[output:88036ffd]
plot(t, x(:,1), 'k', 'LineWidth', 1.2); hold on; %[output:88036ffd]
plot(t, x_hat(:,1), 'b', 'LineWidth', 1.2); %[output:88036ffd]
plot(t, x_hat_noise(:,1), 'r--', 'LineWidth', 1.2); %[output:88036ffd]
legend('True displacement', 'Estimated (no noise)', 'Estimated (with noise)'); %[output:88036ffd]
xlabel('Time (s)'); %[output:88036ffd]
ylabel('Displacement (m)'); %[output:88036ffd]
title('Displacement Comparison'); %[output:88036ffd]
grid on; %[output:88036ffd]

% --- Velocity ---
subplot(2,2,2); %[output:88036ffd]
plot(t, x(:,2), 'k', 'LineWidth', 1.2); hold on; %[output:88036ffd]
plot(t, x_hat(:,2), 'b', 'LineWidth', 1.2); %[output:88036ffd]
plot(t, x_hat_noise(:,2), 'r--', 'LineWidth', 1.2); %[output:88036ffd]
legend('True velocity', 'Estimated (no noise)', 'Estimated (with noise)'); %[output:88036ffd]
xlabel('Time (s)'); %[output:88036ffd]
ylabel('Velocity (m/s)'); %[output:88036ffd]
title('Velocity Comparison'); %[output:88036ffd]
grid on; %[output:88036ffd]

% --- Error in displacement ---
subplot(2,2,3); %[output:88036ffd]
plot(t, x(:,1)-x_hat(:,1), 'b', 'LineWidth', 1.2); hold on; %[output:88036ffd]
plot(t, x(:,1)-x_hat_noise(:,1), 'r--', 'LineWidth', 1.2); %[output:88036ffd]
legend('Error (no noise)', 'Error (with noise)'); %[output:88036ffd]
xlabel('Time (s)'); %[output:88036ffd]
ylabel('Displacement Error (m)'); %[output:88036ffd]
title('Displacement Estimation Error'); %[output:88036ffd]
grid on; %[output:88036ffd]

% --- Error in velocity ---
subplot(2,2,4); %[output:88036ffd]
plot(t, x(:,2)-x_hat(:,2), 'b', 'LineWidth', 1.2); hold on; %[output:88036ffd]
plot(t, x(:,2)-x_hat_noise(:,2), 'r--', 'LineWidth', 1.2); %[output:88036ffd]
legend('Error (no noise)', 'Error (with noise)'); %[output:88036ffd]
xlabel('Time (s)'); %[output:88036ffd]
ylabel('Velocity Error (m/s)'); %[output:88036ffd]
title('Velocity Estimation Error'); %[output:88036ffd]
grid on; %[output:88036ffd]

sgtitle('Observer Performance: Noise-Free vs Noisy Measurements'); %[output:88036ffd]

%% ---------------------- Nested Functions ----------------------
% --- System dynamics ---
function dx = smd(x, A, B, u)
    dx = A*x + B*u;
end

% --- Observer dynamics ---
function dx_hat = obs(t_o, x_hat, A, B, C, u, Ke, y, t)
    y_interp = interp1(t, y, t_o);  % interpolate measurement
    dx_hat = A*x_hat + B*u + Ke*(y_interp - C*x_hat);
end

